  const data = window.__PTU_MOBILE_DATA__;
  if (!data) throw new Error('PTU mobile data bundle must load before Fakemon v2 overlay.');
  const packId = String(pack.manifest.id);
  const sourceIds = new Set((pack.manifest.source_ids || []).map(String));
  const deep = value => JSON.parse(JSON.stringify(value));

  // Remove the superseded embedded v1.x metadata and records for this pack.
  data.packs = (data.packs || []).filter(p => String(p?.id || '') !== packId);
  for (const [versionId, record] of Object.entries(data.records || {})) {
    if (String(record?.contentPackId || '') === packId) delete data.records[versionId];
  }
  for (const [key, versionIds] of Object.entries(data.versionGroups || {})) {
    const next = (versionIds || []).filter(versionId => data.records?.[versionId]);
    if (next.length) data.versionGroups[key] = next; else delete data.versionGroups[key];
  }

  const packMeta = {
    id: packId, name: String(pack.manifest.name || packId), version: String(pack.manifest.version || '0.0.0'),
    priority: Number(pack.manifest.priority ?? 100) || 100, kind: String(pack.manifest.kind || 'custom'),
    browse_only: !!pack.manifest.browse_only, archive_filename: pack.archiveFilename, archive_sha256: pack.archiveSha256,
    manifest: deep(pack.manifest), androidImported: false, bundledRuntimeOverlay: true
  };
  data.packs.push(packMeta);

  const toRecord = (kind, row) => {
    const raw = deep(row || {});
    const logical = String(raw.logical_id || raw.id || '').trim();
    if (!logical) throw new Error(`Bundled ${kind} record is missing logical_id/id.`);
    const versionId = String(raw.definition_version_id || `${kind}:${logical}@${packId}`);
    raw.logical_id = logical; raw.definition_version_id = versionId; raw.content_pack_id = packId;
    const tags = Array.isArray(raw.tags) ? raw.tags : [];
    return {
      kind, id: logical, name: raw.name || raw.display_name || logical, versionId, contentPackId: packId,
      packName: packMeta.name, packKind: packMeta.kind, sourceId: String(raw.source_id || pack.manifest.source_ids?.[0] || packId),
      sourcePage: raw.source_page == null ? null : Number(raw.source_page), priority: Number(raw.source_priority ?? packMeta.priority) || packMeta.priority,
      pinned: false, needsReview: !!raw.needs_review, type: raw.type || (Array.isArray(raw.types) ? raw.types.join(' / ') : null),
      category: raw.class || raw.category || raw.record_kind || raw.capability_kind || null, parentClass: raw.parent_class || null, tags,
      trainingFeature: raw.training_feature === true || tags.some(t => String(t).toLowerCase() === 'training'), profession: raw.profession || null,
      frequency: raw.frequency_text || raw.frequency_action_text || raw.frequency?.raw || null, effect: raw.effect_text || null,
      prerequisites: raw.prerequisites_text || null, price: raw.price ?? null, damageBase: raw.damage_base ?? null, ac: raw.ac ?? null,
      range: raw.range_text || null, contestType: raw.contest_type || null, contestEffect: raw.contest_effect || null,
      dexNumber: raw.dex_number ?? raw.national_dex_number ?? null, enabledForCreation: raw.enabled_for_character_creation ?? null,
      completeness: raw.mechanical_completeness || null, types: Array.isArray(raw.types) ? raw.types : [], baseStats: raw.base_stats || null,
      abilities: raw.ability_slots || [], capabilities: raw.capabilities || [], levelUpMoves: raw.level_up_moves || [], raw, rawText: raw.raw_text || null,
      semanticAutomation: raw.semantic_automation || null, compiledEffects: raw.compiled_effects || [], prerequisiteSemantics: raw.prerequisite_semantics || null,
      defenseProfile: raw.type_defense_profile || null, evolution: raw.evolution || null, evolutionText: raw.evolution_text || null, skills: raw.skills || null,
      skillsText: raw.skills_text || null, capabilitiesText: raw.capabilities_text || null, tmMoves: raw.tm_moves || [], tutorMoves: raw.tutor_moves || [],
      eggMoves: raw.egg_moves || [], androidImported: false, bundledRuntimeOverlay: true
    };
  };

  const affected = [];
  data.records ||= {}; data.versionGroups ||= {};
  for (const [kind, rows] of Object.entries(pack.definitions || {})) {
    for (const row of (Array.isArray(rows) ? rows : [])) {
      const record = toRecord(kind, row);
      data.records[record.versionId] = record;
      const key = `${kind}:${record.id}`;
      data.versionGroups[key] = [...(data.versionGroups[key] || []).filter(v => v !== record.versionId), record.versionId];
      affected.push([kind, record.id, record.versionId]);
    }
  }

  data.evolutionEdges = (data.evolutionEdges || []).filter(edge => !sourceIds.has(String(edge?.source_id || '')));
  for (const edge of (pack.evolutionEdges || [])) data.evolutionEdges.push({...deep(edge), raw: deep(edge.raw || edge)});
  if (Array.isArray(data.evolutionFamilies)) {
    data.evolutionFamilies = data.evolutionFamilies.filter(family => !sourceIds.has(String(family?.source_id || '')));
    data.evolutionFamilies.push(...(pack.evolutionFamilies || []).map(deep));
  }

  for (const ruleset of (data.rulesets || [])) {
    const existing = (ruleset.packs || []).find(p => String(p?.pack_id || '') === packId);
    const shouldInclude = !!existing || String(ruleset.id) === 'all-provided-material';
    ruleset.packs = (ruleset.packs || []).filter(p => String(p?.pack_id || '') !== packId);
    if (!shouldInclude) continue;
    const maxPosition = Math.max(-1, ...ruleset.packs.map(p => Number(p.position ?? -1)));
    const enabled = existing ? !!existing.enabled : true;
    ruleset.packs.push({
      pack_id: packId, enabled, priority: packMeta.priority, position: existing?.position ?? (maxPosition + 1),
      name: packMeta.name, kind: packMeta.kind, browse_only: packMeta.browse_only, version: packMeta.version, androidImported: false, bundledRuntimeOverlay: true
    });
    data.resolved ||= {}; data.resolved[ruleset.id] ||= {};
    for (const [kind, logicalId, versionId] of affected) {
      data.resolved[ruleset.id][kind] ||= {};
      if (enabled) data.resolved[ruleset.id][kind][logicalId] = versionId;
    }
  }

  window.__PTU_BOOKS_SPECIES_BUNDLED_PACK__ = pack;
